  S.weeks++; kDay(7);
  const over = (S.list - S.trueP) / S.trueP, speed = K.repair ? K.repair.speed : 0, slow = KP.stars >= 5 ? 0.12 : KP.stars >= 3 ? 0.05 : 0;
  const p = Math.max(0.06, Math.min(0.9, 0.45 - over * 4 + speed - slow));
  if(S.weeks === 1 && S.list > KP.list[3]){ S.offer = {amt:KP.list[3], buyer:K_BUYERS[1], script:true}; return; }
  if(K.r() < p){ const b = K_BUYERS[Math.floor(K.r() * K_BUYERS.length)]; const amt = Math.min(S.list, Math.round(S.trueP * (1 - b.flex - K.r() * 0.01) / 10) * 10); S.offer = {amt, buyer:b}; }
