  let style = STY[top]; if(K.style.research >= 4) style = ["현장조사 탐정","입찰 전에 발로 뛰어 숨은 위험을 먼저 찾는 타입"];
  K.final = {total, profit, rate:profit / total * 100, found, hid, grades, tips, style, lesson:(K_LESSONS[K.lessonKey] && K.lessonKey && K.lessonKey.startsWith("kf_") ? K_LESSONS[K.lessonKey] + " " : "") + KP.lesson};
